constructor(card, directoryHint) {
  super();
  this.card = card;
  if (directoryHint) {
    this.directory = directoryHint;
  } else {
    this.directory = MailServices.ab.getDirectoryFromUID(
      this.card.directoryUID
    );
  }
  if (this.card.isMailList) {
    this.addProperty("mailing-list");
  }
}
